begin;
select no_plan();
select has_table('public','graduate_students','MSc register exists');
select ok((select relrowsecurity from pg_class where oid='public.graduate_students'::regclass),'Students have RLS');
select ok((select relrowsecurity from pg_class where oid='public.graduate_task_records'::regclass),'Task records have RLS');
select ok(not has_table_privilege('anon','public.graduate_students','SELECT'),'Anonymous users cannot read student details');
select ok(not has_table_privilege('anon','public.graduate_task_records','INSERT'),'Anonymous users cannot record reports');

set local role authenticated;
set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000001';
select lives_ok($$insert into public.graduate_students(id,student_number,student_name,supervisor_name,start_date,organization_unit_id) values('90000000-0000-0000-0000-000000000001','MSC-TEST-001','Graduate Test','Supervisor','2024-09-01','10000000-0000-0000-0000-000000000002')$$,'Dean can create a student');
select is((select count(*) from public.graduate_categories where student_id='90000000-0000-0000-0000-000000000001'),5::bigint,'Student creation seeds five planning sections');
select lives_ok($$update public.graduate_students set committee_members=array['Dr. Member'],committee_chair='Dr. Member',university_examiner='Dr. Examiner',defence_date='2026-08-31',thesis_submission_date='2026-07-01' where id='90000000-0000-0000-0000-000000000001'$$,'Committee appointments and a custom submission date can be saved');
select is((select committee_chair from public.graduate_students where id='90000000-0000-0000-0000-000000000001'),'Dr. Member','Committee chair persists');
select is((select university_examiner from public.graduate_students where id='90000000-0000-0000-0000-000000000001'),'Dr. Examiner','University Examiner persists');
select throws_ok($$update public.graduate_students set committee_chair='Not a member' where id='90000000-0000-0000-0000-000000000001'$$,'23514',null,'Committee chair must belong to the committee');
select throws_ok($$update public.graduate_students set thesis_submission_date='2026-09-01' where id='90000000-0000-0000-0000-000000000001'$$,'23514',null,'Submission cannot be scheduled after defense');
select throws_ok($$update public.graduate_students set thesis_submission_date='2024-08-31' where id='90000000-0000-0000-0000-000000000001'$$,'23514',null,'Submission cannot precede program start');
select lives_ok($$insert into public.graduate_task_records(student_id,task_key,course_semester_start,expected_on) values('90000000-0000-0000-0000-000000000001','course:5','2025-01-01','2025-04-30')$$,'A course spans a whole semester');
select throws_ok($$update public.graduate_task_records set expected_on='2025-04-15' where student_id='90000000-0000-0000-0000-000000000001' and task_key='course:5'$$,'23514',null,'Assigned course deadline must be semester end');
select throws_ok($$update public.graduate_task_records set course_semester_start='2025-02-01',expected_on='2025-05-31' where student_id='90000000-0000-0000-0000-000000000001' and task_key='course:5'$$,'23514',null,'Course must start on a semester boundary');
select throws_ok($$insert into public.graduate_task_records(student_id,task_key,course_semester_start,expected_on) values('90000000-0000-0000-0000-000000000001','course:5','2025-05-01','2025-08-31')$$,'23505',null,'One course assignment per requirement');
select lives_ok($$insert into public.graduate_task_records(student_id,task_key,is_draft,expected_on) values('90000000-0000-0000-0000-000000000001','chapter:results',true,'2026-06-27')$$,'A chapter can have a saved draft status and planned date');
select lives_ok($$update public.graduate_task_records set planned_start_on='2026-04-15',item_type='Thesis' where student_id='90000000-0000-0000-0000-000000000001' and task_key='chapter:results'$$,'Chapter start and symbol can be saved');
select is((select planned_start_on from public.graduate_task_records where student_id='90000000-0000-0000-0000-000000000001' and task_key='chapter:results'),'2026-04-15'::date,'Custom chapter start persists');
select throws_ok($$update public.graduate_task_records set planned_start_on='2026-07-01' where student_id='90000000-0000-0000-0000-000000000001' and task_key='chapter:results'$$,'23514',null,'Chapter start cannot follow its deadline');
select throws_ok($$update public.graduate_task_records set item_type='Unknown' where student_id='90000000-0000-0000-0000-000000000001' and task_key='chapter:results'$$,'23514',null,'Invalid item symbols are rejected');
select throws_ok($$insert into public.graduate_task_records(student_id,task_key,planned_start_on) values('90000000-0000-0000-0000-000000000001','course:1','2026-01-01')$$,'23514',null,'Writing start dates only apply to chapters');
select throws_ok($$update public.graduate_task_records set completed_on='2026-06-27' where student_id='90000000-0000-0000-0000-000000000001' and task_key='chapter:results'$$,'23514',null,'A chapter cannot simultaneously be draft and completed');
select lives_ok($$update public.graduate_task_records set is_draft=false,completed_on='2026-06-27' where student_id='90000000-0000-0000-0000-000000000001' and task_key='chapter:results'$$,'A chapter can transition from draft to completed');
select lives_ok($$insert into public.graduate_task_records(student_id,task_key,completed_on) values('90000000-0000-0000-0000-000000000001','committee:formation','2025-04-30'),('90000000-0000-0000-0000-000000000001','committee:meeting:2024-09-01','2024-12-20')$$,'Committee formation and semester meetings can be recorded');
select lives_ok($$insert into public.graduate_categories(student_id,key,name,color,sort_order) values('90000000-0000-0000-0000-000000000001','thesis','Thesis progress','#9333ea',5)$$,'Dean can add a category');
select lives_ok($$insert into public.graduate_deadlines(id,student_id,category_key,title,due_date) values('91000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001','thesis','Proposal review','2026-10-15')$$,'Dean can save a custom deadline');
select lives_ok($$update public.graduate_deadlines set item_type='Meeting' where id='91000000-0000-0000-0000-000000000001'$$,'Custom deadline symbol can be set');
select is((select item_type from public.graduate_deadlines where id='91000000-0000-0000-0000-000000000001'),'Meeting','Custom deadline symbol persists');
select lives_ok($$insert into public.graduate_task_records(student_id,task_key,expected_on) values('90000000-0000-0000-0000-000000000001','course:2','2026-12-31')$$,'Course milestones can be planned without completion');
select throws_ok($$insert into public.graduate_task_records(student_id,task_key,expected_on) values('90000000-0000-0000-0000-000000000001','form-office','2026-12-31')$$,'23514',null,'Computed defence deadlines cannot be overridden by a course plan');
select lives_ok($$insert into public.graduate_tracker_links(student_id,tracker_id) values('90000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000003')$$,'Dean can link a permitted tracker');
select ok(not has_table_privilege('anon','public.graduate_categories','SELECT'),'Anonymous users cannot read categories');
select ok(not has_table_privilege('anon','public.graduate_deadlines','SELECT'),'Anonymous users cannot read deadlines');
select ok(not has_table_privilege('anon','public.graduate_tracker_links','SELECT'),'Anonymous users cannot read tracker links');
select throws_ok($$insert into public.graduate_students(student_number,student_name,supervisor_name,start_date) values('MSC-INVALID','Invalid','Supervisor','2024-09-02')$$,'23514',null,'Starts must be the first day of a semester');
select throws_ok($$update public.graduate_students set defence_date='2024-08-01' where id='90000000-0000-0000-0000-000000000001'$$,'23514',null,'Defence cannot precede admission');
select lives_ok($$insert into public.graduate_task_records(student_id,task_key,completed_on,notes) values('90000000-0000-0000-0000-000000000001','report:2024-09-01','2024-12-30','Received')$$,'Dean can record a semester report');
select throws_ok($$update public.graduate_students set created_by='00000000-0000-0000-0000-000000000002' where id='90000000-0000-0000-0000-000000000001'$$,'42501',null,'Record ownership cannot be reassigned');

set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000003';
select is((select count(*) from public.graduate_students where id='90000000-0000-0000-0000-000000000001'),0::bigint,'Chair outside the unit cannot read a student');
with changed as (update public.graduate_students set university_examiner='Forbidden' where id='90000000-0000-0000-0000-000000000001' returning id) select is((select count(*) from changed),0::bigint,'Out-of-scope staff cannot change committee appointments');
select is((select count(*) from public.graduate_task_records where student_id='90000000-0000-0000-0000-000000000001'),0::bigint,'Chair outside the unit cannot read reports');
select is((select count(*) from public.graduate_categories where student_id='90000000-0000-0000-0000-000000000001'),0::bigint,'Chair outside the unit cannot read categories');
select is((select count(*) from public.graduate_deadlines where student_id='90000000-0000-0000-0000-000000000001'),0::bigint,'Chair outside the unit cannot read custom deadlines');
select throws_ok($$insert into public.graduate_categories(student_id,key,name,color) values('90000000-0000-0000-0000-000000000001','blocked','Blocked','#9333ea')$$,'42501',null,'Chair cannot add out-of-scope categories');
select throws_ok($$insert into public.graduate_task_records(student_id,task_key) values('90000000-0000-0000-0000-000000000001','oral-exam')$$,'42501',null,'Out-of-scope report writes are denied');

set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000002';
select is((select count(*) from public.graduate_students where id='90000000-0000-0000-0000-000000000001'),0::bigint,'Unassigned instructor in the same unit cannot read a student');
select throws_ok($$insert into public.graduate_students(student_number,student_name,supervisor_name,start_date,organization_unit_id) values('MSC-FORBIDDEN','Invalid','Supervisor','2024-09-01','10000000-0000-0000-0000-000000000002')$$,'42501',null,'Instructors cannot create students');

set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000001';
select lives_ok($$update public.graduate_students set supervisor_id='00000000-0000-0000-0000-000000000002' where id='90000000-0000-0000-0000-000000000001'$$,'Dean can assign a supervisor account');
set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000002';
select is((select count(*) from public.graduate_students where id='90000000-0000-0000-0000-000000000001'),1::bigint,'Assigned supervisor can read student');
select lives_ok($$update public.graduate_task_records set notes='Reviewed by supervisor' where student_id='90000000-0000-0000-0000-000000000001'$$,'Assigned supervisor can update report');
select is((select notes from public.graduate_task_records where student_id='90000000-0000-0000-0000-000000000001' and task_key='report:2024-09-01'),'Reviewed by supervisor','Updated report persists');
select lives_ok($$update public.graduate_students set defence_date='2026-08-31' where id='90000000-0000-0000-0000-000000000001'$$,'Assigned supervisor can reschedule defence');
select lives_ok($$update public.graduate_categories set color='#be123c' where student_id='90000000-0000-0000-0000-000000000001' and key='thesis'$$,'Assigned supervisor can change section colors');
select is((select color from public.graduate_categories where student_id='90000000-0000-0000-0000-000000000001' and key='thesis'),'#be123c','Section color persists');
select lives_ok($$update public.graduate_deadlines set due_date='2026-11-15' where id='91000000-0000-0000-0000-000000000001'$$,'Assigned supervisor can reschedule custom deadline');
select is((select count(*) from public.graduate_tracker_links where student_id='90000000-0000-0000-0000-000000000001'),0::bigint,'Student access alone does not expose a restricted linked tracker');
select throws_ok($$insert into public.graduate_tracker_links(student_id,tracker_id) values('90000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000002')$$,'42501',null,'Supervisor cannot link a tracker they cannot access');

set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000001';
select is((select supervisor_name from public.graduate_students where id='90000000-0000-0000-0000-000000000001'),'Dr. Alex Mercer','Supervisor name is resolved from the selected account');
select lives_ok($$update public.graduate_students set co_supervisor_id='00000000-0000-0000-0000-000000000003' where id='90000000-0000-0000-0000-000000000001'$$,'Dean can assign an optional co-supervisor');
select is((select co_supervisor_name from public.graduate_students where id='90000000-0000-0000-0000-000000000001'),'Prof. Karen Vance','Co-supervisor name is resolved from the selected account');
select throws_ok($$update public.graduate_students set co_supervisor_id=supervisor_id where id='90000000-0000-0000-0000-000000000001'$$,'23514',null,'Primary and co-supervisor must be different accounts');
set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000003';
select is((select count(*) from public.graduate_students where id='90000000-0000-0000-0000-000000000001'),1::bigint,'Assigned co-supervisor can read student outside their unit');
select lives_ok($$update public.graduate_task_records set notes='Reviewed by co-supervisor' where student_id='90000000-0000-0000-0000-000000000001' and task_key='chapter:results'$$,'Co-supervisor can update chapter progress');
select is((select notes from public.graduate_task_records where student_id='90000000-0000-0000-0000-000000000001' and task_key='chapter:results'),'Reviewed by co-supervisor','Co-supervisor chapter update persists');
set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000001';
select lives_ok($$update public.graduate_students set co_supervisor_id=null where id='90000000-0000-0000-0000-000000000001'$$,'Co-supervisor assignment can be removed');
set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000003';
select is((select count(*) from public.graduate_students where id='90000000-0000-0000-0000-000000000001'),0::bigint,'Removing co-supervisor revokes access');

reset role;
update public.profiles set is_active=false where id='00000000-0000-0000-0000-000000000002';
set local role authenticated;
set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000002';
select is((select count(*) from public.graduate_students where id='90000000-0000-0000-0000-000000000001'),0::bigint,'Inactive supervisors lose access');
select * from finish();
rollback;
